cat > ~/bin/git-ssh-check.sh <<'EOF'
#!/bin/bash
u=$(git remote get-url origin 2>/dev/null) || { echo 'brak origin'; exit 1; }
echo "origin: $u"
case "$u" in
    https://*) echo 'UWAGA: HTTPS - zmien: git remote set-url origin git@github.com:...';;
    git@*|ssh://*) echo 'SSH OK';;
esac
EOF
chmod +x ~/bin/git-ssh-check.sh
cd ~/projekty/sklep && ~/bin/git-ssh-check.sh
